Residual std 0.097 matches the noise, so the rule is f(x)=0.608 sin(11.1x+0.102)+0.842 sin(14.15x+2.834)+0.400 sin(19.85x-2.901). Building the net as a piecewise-linear interpolant of f: l1 makes sharp silu ramps at 46 knots plus one linear ramp, l2 passes them through with a +12 offset where silu is nearly identity, l3 holds the slope changes.
```python
def f(t):
    return -0.005+0.605*np.sin(11.1*t)+0.062*np.cos(11.1*t)-0.802*np.sin(14.15*t)+0.255*np.cos(14.15*t)-0.388*np.sin(19.85*t)-0.095*np.cos(19.85*t)
def f2(t):
    return -(11.1**2)*(0.605*np.sin(11.1*t)+0.062*np.cos(11.1*t))-(14.15**2)*(-0.802*np.sin(14.15*t)+0.255*np.cos(14.15*t))-(19.85**2)*(-0.388*np.sin(19.85*t)-0.095*np.cos(19.85*t))
def build(k,C=12.0,corr=True):
    n=np.linspace(-1.0,1.0,48); h=n[1]-n[0]
    v=f(n)+(f2(n)*h*h/12 if corr else 0)
    s=np.diff(v)/h                      # 47 segment slopes
    t=np.zeros(48); w1=np.full(48,k); c=np.zeros(48)
    t[0]=-1.5; c[0]=s[0]
    t[1:47]=n[1:47]; c[1:47]=np.diff(s)
    w1[47]=0.0; t[47]=0.0; c[47]=0.0
    b0=v[0]-s[0]*(n[0]-t[0])
    W1=w1[:,None]; B1=-w1*t
    W2=np.eye(48)/k; B2=np.full(48,C)
    W3=c[None,:]; B3=np.array([b0-C*c.sum()])
    return W1,B1,W2,B2,W3,B3
def silu(z): return z/(1+np.exp(-z))
def fwd(P,x):
    W1,B1,W2,B2,W3,B3=P
    a=silu(x[:,None]@W1.T+B1); a=silu(a@W2.T+B2); return (a@W3.T+B3).ravel()
g=np.linspace(-1,1,4001); fg=f(g)
x=np.load("train_x.npy").ravel().astype(float); y=np.load("train_y.npy").ravel().astype(float)
for k in [20,30,50,80,150]:
  for corr in [False,True]:
    P=build(k,corr=corr); e=fwd(P,g)-fg
    print(k,corr,"rms vs f",np.sqrt((e**2).mean()).round(4),"max",np.abs(e).max().round(3),"R2 train",(1-((y-fwd(P,x))**2).mean()/y.var()).round(4))
